"use client";
import { useEffect, useMemo, useRef, useState } from "react";

type Product = "search" | "bmap" | "translate" | "news" | "bazlens";
type AppInfo = { slug: Product; label: string; port: number; detail: string };

const APPS: AppInfo[] = [
  { slug: "search", label: "Search", port: 3020, detail: "Find anything across the web and beyond" },
  { slug: "bmap", label: "BMap", port: 3038, detail: "Explore places, businesses and local information" },
  { slug: "translate", label: "Translate", port: 3039, detail: "Translate text, documents and conversations" },
  { slug: "news", label: "News", port: 3040, detail: "Follow trusted stories and global perspectives" },
  { slug: "bazlens", label: "BazLens", port: 3041, detail: "Search what you see with visual intelligence" },
];

function appUrl(slug: string, port: number): string | null {
  try {
    const configured = JSON.parse(process.env.NEXT_PUBLIC_BAZAARA_APP_URLS || "{}");
    if (configured && typeof configured[slug] === "string" && /^https:\/\/[^\s]+$/i.test(configured[slug])) return configured[slug];
  } catch { /* Optional deployment configuration. */ }
  if (typeof window === "undefined") return null;
  const host = window.location.hostname;
  const local = ["localhost", "127.0.0.1", "::1"].includes(host) || /^(10|192\.168|172\.(1[6-9]|2\d|3[01]))\./.test(host);
  return local ? `${window.location.protocol}//${host.includes(":") ? `[${host}]` : host}:${port}/` : null;
}

function ProductIcon({ slug }: { slug: Product }) {
  const id = `bzi7-${slug}-gradient`;
  if (slug === "search") return <svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id={id} x1="10" y1="8" x2="54" y2="56"><stop stopColor="#7C3CFF"/><stop offset=".48" stopColor="#0A7BFF"/><stop offset="1" stopColor="#21E3E0"/></linearGradient></defs><circle cx="28" cy="28" r="16" fill="none" stroke={`url(#${id})`} strokeWidth="8"/><path d="M40 40 54 54" fill="none" stroke={`url(#${id})`} strokeWidth="8" strokeLinecap="round"/></svg>;
  if (slug === "bmap") return <svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id={id} x1="12" y1="8" x2="50" y2="58"><stop stopColor="#CA2BFF"/><stop offset=".42" stopColor="#6534FF"/><stop offset=".75" stopColor="#0A9CFF"/><stop offset="1" stopColor="#19E5DC"/></linearGradient></defs><path d="M32 6c-12.1 0-22 9.5-22 21.4C10 43.5 32 58 32 58s22-14.5 22-30.6C54 15.5 44.1 6 32 6Z" fill={`url(#${id})`}/><circle cx="32" cy="28" r="7" fill="#F7FAFF"/><circle cx="32" cy="28" r="3" fill="#6C35FF"/></svg>;
  if (slug === "translate") return <svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id={id} x1="8" y1="10" x2="58" y2="54"><stop stopColor="#EA2BFF"/><stop offset=".48" stopColor="#6650FF"/><stop offset="1" stopColor="#19D8E6"/></linearGradient></defs><rect x="9" y="10" width="22" height="40" rx="8" fill={`url(#${id})`}/><rect x="28" y="16" width="27" height="38" rx="8" fill="#F8FBFF" fillOpacity=".96"/><path d="M34 27h15M34 34h13M34 41h10" stroke={`url(#${id})`} strokeWidth="4" strokeLinecap="round"/></svg>;
  if (slug === "news") return <svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id={id} x1="10" y1="10" x2="54" y2="54"><stop stopColor="#7137FF"/><stop offset=".5" stopColor="#0D8BFF"/><stop offset="1" stopColor="#29E1DA"/></linearGradient></defs><rect x="10" y="9" width="44" height="46" rx="12" fill={`url(#${id})`}/><rect x="18" y="17" width="28" height="8" rx="4" fill="#fff" fillOpacity=".94"/><path d="M18 32h28M18 39h22M18 46h15" stroke="#fff" strokeOpacity=".92" strokeWidth="4" strokeLinecap="round"/></svg>;
  return <svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id={id} x1="8" y1="8" x2="56" y2="58"><stop stopColor="#EA2BFF"/><stop offset=".36" stopColor="#6039FF"/><stop offset=".7" stopColor="#078BFF"/><stop offset="1" stopColor="#20E3DD"/></linearGradient></defs><path d="M32 7 57 51H7L32 7Z" fill={`url(#${id})`}/><circle cx="32" cy="35" r="13" fill="#0B1740" stroke="#E7F6FF" strokeOpacity=".72" strokeWidth="2"/><circle cx="32" cy="35" r="8" fill="#2646A2"/><circle cx="35" cy="32" r="3" fill="#9DEBFF"/></svg>;
}

export default function InternetDock({ current }: { current: Product }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [urls, setUrls] = useState<Record<string, string | null>>({});
  const [favorites, setFavorites] = useState<Product[]>([]);
  const searchRef = useRef<HTMLInputElement>(null);
  const launchRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    try {
      const saved = JSON.parse(localStorage.getItem("bazaara.internet.favorites") || "[]");
      if (Array.isArray(saved)) setFavorites(saved.filter((item): item is Product => APPS.some(app => app.slug === item)));
    } catch { /* Preferences are optional. */ }
  }, []);

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.altKey && event.key.toLowerCase() === "i") { event.preventDefault(); setOpen(value => !value); }
      if (event.key === "Escape") setOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  useEffect(() => {
    if (open) {
      setUrls(Object.fromEntries(APPS.map(app => [app.slug, appUrl(app.slug, app.port)])));
      requestAnimationFrame(() => searchRef.current?.focus());
    } else {
      launchRef.current?.focus();
    }
  }, [open]);

  const list = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    const source = normalized ? APPS.filter(app => `${app.label} ${app.detail}`.toLowerCase().includes(normalized)) : APPS;
    return [...source].sort((a, b) => Number(favorites.includes(b.slug)) - Number(favorites.includes(a.slug)));
  }, [query, favorites]);

  const toggleFavorite = (slug: Product) => {
    setFavorites(previous => {
      const next = previous.includes(slug) ? previous.filter(item => item !== slug) : [...previous, slug];
      try { localStorage.setItem("bazaara.internet.favorites", JSON.stringify(next)); } catch { /* Ignore storage restrictions. */ }
      return next;
    });
  };

  return <div className="bzi7-root">
    <button ref={launchRef} type="button" className="bzi7-launch" onClick={() => setOpen(value => !value)} aria-label="Open all BAZAARA Internet apps (Alt+I)" aria-haspopup="dialog" aria-expanded={open}>
      <span className="bzi7-launch-grid" aria-hidden="true"><i/><i/><i/><i/></span>
      <span className="bzi7-launch-label">All apps</span>
    </button>

    {open && <div className="bzi7-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) setOpen(false); }}>
      <section className="bzi7-shell" role="dialog" aria-modal="true" aria-label="BAZAARA Internet suite">
        <div className="bzi7-aurora bzi7-aurora-a"/><div className="bzi7-aurora bzi7-aurora-b"/><div className="bzi7-aurora bzi7-aurora-c"/>

        <header className="bzi7-topbar">
          <div className="bzi7-brand">
            <span className="bzi7-menu" aria-hidden="true"><i/><i/><i/></span>
            <img src="/bazaara-ribbon-b.svg" alt=""/>
            <span><strong>BAZAARA</strong><small>INTERNET</small></span>
          </div>
          <label className="bzi7-global-search">
            <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m16.2 16.2 4.3 4.3"/></svg>
            <input ref={searchRef} value={query} onChange={event => setQuery(event.target.value)} type="search" placeholder="Search Internet apps" aria-label="Search Internet apps"/>
            <kbd>Alt + I</kbd>
          </label>
          <div className="bzi7-account" title="BazID account"><span>B</span></div>
          <button type="button" className="bzi7-close" aria-label="Close Internet apps" onClick={() => setOpen(false)}>×</button>
        </header>

        <div className="bzi7-heading">
          <div><span>BAZAARA / INTERNET</span><h2>Discover the web, beautifully.</h2><p>Five focused products. One connected BAZAARA experience.</p></div>
          <div className="bzi7-status"><i/><span>5 services</span><small>Connected</small></div>
        </div>

        <div className="bzi7-grid">
          {list.map(app => {
            const url = urls[app.slug];
            const isFavorite = favorites.includes(app.slug);
            return <article className={`bzi7-card ${current === app.slug ? "bzi7-active" : ""}`} key={app.slug}>
              <div className={`bzi7-icon bzi7-icon-${app.slug}`}><ProductIcon slug={app.slug}/></div>
              <button className={`bzi7-star ${isFavorite ? "bzi7-star-on" : ""}`} type="button" aria-label={`${isFavorite ? "Remove" : "Add"} ${app.label} ${isFavorite ? "from" : "to"} favorites`} aria-pressed={isFavorite} onClick={() => toggleFavorite(app.slug)}>★</button>
              {current === app.slug && <span className="bzi7-current">CURRENT</span>}
              <div className="bzi7-card-copy"><h3>{app.label}</h3><p>{app.detail}</p></div>
              <div className="bzi7-card-bottom">
                {url ? <a href={url} onClick={() => setOpen(false)}>Open <span>›</span></a> : <span className="bzi7-disabled" title="Configure NEXT_PUBLIC_BAZAARA_APP_URLS for production">Unavailable</span>}
                <span className="bzi7-port">:{app.port}</span>
              </div>
            </article>;
          })}
          {list.length === 0 && <div className="bzi7-empty"><strong>No matching apps</strong><span>Try Search, BMap, Translate, News or BazLens.</span></div>}
        </div>

        <footer className="bzi7-footer"><span><img src="/bazaara-ribbon-b.svg" alt=""/> Connected by the BAZAARA platform</span><span>One account · BazID · Secure infrastructure</span></footer>
      </section>
    </div>}
  </div>;
}
